=== 3. Fix — Option B (same behavior, extracted helper; use if you want the `makeLabelsByCustomizedTicks` shape) ===

Replace the whole of lines 123-149 with:

```ts
export function createAxisLabels(axis: Axis, ctx: AxisLabelsComputingContext): {
    labels: AxisLabelInfoDetermined[]
} {
    const custom = axis.getLabelModel().get('customValues');
    if (custom) {
        return {labels: makeLabelsByCustomizedTicks(axis, custom)};
    }
    // Only ordinal scale support tick interval
    return axis.type === 'category'
        ? makeCategoryLabels(axis, ctx)
        : makeRealNumberLabels(axis);
}

/**
 * Build labels from `axisLabel.customValues`.
 * The index passed to the formatter must be the index of the rendered item in this
 * filtered label list, taken directly from the mapping. Do not look it up by value
 * (e.g. `indexOf`), which collapses duplicated values onto the first matching position.
 */
function makeLabelsByCustomizedTicks(
    axis: Axis, customValues: (number | string | Date)[]
): AxisLabelInfoDetermined[] {
    const labelFormatter = makeLabelFormatter(axis);
    const extent = axis.scale.getExtent();
    const tickNumbers = tickValuesToNumbers(axis, customValues);
    const ticks = zrUtil.filter(tickNumbers, val => val >= extent[0] && val <= extent[1]);
    return zrUtil.map(ticks, (numval, index) => {
        const tick = {value: numval};
        return {
            formattedLabel: labelFormatter(tick, index),
            rawLabel: axis.scale.getLabel(tick),
            tickValue: numval,
            time: undefined as ScaleTick['time'] | NullUndefined,
            break: undefined as VisualAxisBreak | NullUndefined,
        };
    });
}
```
(Function declarations hoist, so placing the helper right after `createAxisLabels` is fine. `custom` is typed `(number | string | Date)[]` from `AxisLabelBaseOption['customValues']`, src/coord/axisCommonTypes.ts:322, which matches `tickValuesToNumbers(axis: Axis, values: (number | string | Date)[])` at line 111.)

