```ts
/**
 * The sign, expressed in the "bar length" measure below, that a positive value
 * points to. The measure is:
 *  - cartesian: `layout.height` (vertical bar) / `layout.width` (horizontal bar)
 *  - polar: `layout.r - layout.r0` (radial) / `layout.endAngle - layout.startAngle` (tangential)
 *
 * The measure is reversed w.r.t. the axis direction for the cartesian `height`
 * (pixel y grows downwards, see `updateAxisTransform` in coord/cartesian/Grid.ts)
 * and for the polar angle span (angles are negated in layout/barPolar.ts).
 *
 * Keeps the same convention as `pxSign` in PictorialBarView.ts.
 */
function getBarPositiveSign(
    seriesModel: BarSeriesModel,
    isHorizontalOrRadial: boolean,
    isPolar: boolean
): number {
    const coordSys = seriesModel.coordinateSystem;
    const valueAxis = isPolar
        ? (coordSys as Polar).getAxis(isHorizontalOrRadial ? 'radius' : 'angle')
        : (coordSys as Cartesian2D).getAxis(isHorizontalOrRadial ? 'y' : 'x');
    const measureReversed = isPolar ? !isHorizontalOrRadial : isHorizontalOrRadial;
    return (measureReversed ? -1 : 1) * (valueAxis.inverse ? -1 : 1);
}
```

Axis selection is correct because `isHorizontalOrRadial` is `baseAxis.isHorizontal()` for cartesian and `baseAxis.dim === 'angle'` for polar (`src/chart/bar/BarView.ts:207-212`); the *value* axis is therefore the other one. `Polar.getAxis(dim: 'radius' | 'angle')` is at `src/coord/polar/Polar.ts:83`; `Cartesian2D.getAxis` comes from `Cartesian` (`src/coord/cartesian/Cartesian.ts:41`). Both `Axis2D`, `AngleAxis` and `RadiusAxis` extend `Axis`, so `.inverse` exists on the resulting union.

